import { Hono } from 'hono'
import { cors } from 'hono/cors'
import { logger } from 'hono/logger'
import { secureHeaders } from 'hono/secure-headers'
import { drizzle } from 'drizzle-orm/d1'
import * as schema from './db/schema'

type Bindings = {
  DB: D1Database
  AI: Ai
  APP_ENV: string
  DEFAULT_UNITS: string
  API_TOKEN: string // secret from .dev.vars / wrangler secret
}

const app = new Hono<{ Bindings: Bindings }>()

app.use('*', logger())
app.use('*', secureHeaders())
app.use('/api/*', cors({ origin: ['https://strideguide.app'], allowMethods: ['GET','POST','PATCH','DELETE'] }))

app.get('/health', (c) => c.json({ ok: true, env: c.env.APP_ENV }))

app.get('/api/runs', async (c) => {
  const db = drizzle(c.env.DB, { schema })
  const rows = await db.select().from(schema.runs)
  return c.json(rows)
})

app.post('/api/coach', async (c) => {
  const answer = await c.env.AI.run('@cf/meta/llama-3.1-8b-instruct', {
    prompt: 'Summarize this training week'
  })
  return c.json(answer)
})

// Module worker: Hono fetch + scheduled cron handler
export default {
  fetch: app.fetch,
  async scheduled(controller: ScheduledController, env: Bindings, ctx: ExecutionContext) {
    const db = drizzle(env.DB, { schema })
    ctx.waitUntil(/* nightly rollup job */ Promise.resolve())
  }
}

// Optional: also export app for tests (app.request(...))
export { app }

config_snippets.drizzle_config_ts:
import { defineConfig } from 'drizzle-kit'

export default defineConfig({
  dialect: 'sqlite',
  schema: './src/db/schema.ts',
  out: './drizzle',
  // `driver: 'd1-http'` + dbCredentials are only needed for `drizzle-kit migrate|push|studio`
  // against the REMOTE D1 database (reads CLOUDFLARE_ACCOUNT_ID / CLOUDFLARE_DATABASE_ID / CLOUDFLARE_D1_TOKEN).
  // Use Cloudflare's own account/database IDs, not the D1 binding name.
  driver: 'd1-http',
  dbCredentials: {
    accountId: process.env.CLOUDFLARE_ACCOUNT_ID!,
    databaseId: process.env.CLOUDFLARE_DATABASE_ID!,
    token: process.env.CLOUDFLARE_D1_TOKEN!
  }
})
